import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"周易口訣義 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"周易口訣義 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"classics/koujueyi/013.md","filePath":"classics/koujueyi/013.md"}'),r={name:"classics/koujueyi/013.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><p>彖曰：「泰，小往大來，吉，亨」。則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。</p><p>象曰：天地交，泰，後以財成天地之道，輔相天地之宜，以左右民。</p><p>初九，拔茅茹以其匯，徵吉。</p><p>象曰：「拔茅徵吉」，志在外也。</p><p>九二，包荒，用馮河，不遐遺，朋亡，得尚於中行。</p><p>象曰：「包荒得尚於中行」，以光大也。</p><p>九三，無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福。</p><p>象曰：「無往不復」，天地際也。</p><p>六四，翩翩，不富以其鄰，不戒以孚。</p><p>象曰：「翩翩不富」，皆失實也。「不戒以孚」，中心願也。</p><p>六五，帝乙歸妹，以祉元吉。</p><p>象曰：「以祉元吉」，中以行願也。</p><p>上六，城復於隍，勿用師，自邑告命，貞吝。</p><p>象曰：「城復於隍」，其命亂也。</p><p>解讀</p><p>泰，小往大來，吉亨者，泰是通泰之名，以天地交感，萬物長育，故名「泰」也。陰氣消，故曰「小往」；陽氣長，故曰「大來」。以天地通泰，君子道長，小人道消，以此吉而亨通矣，故曰「吉亨」也。象曰「天地交，泰」者，天氣降下，地氣騰上，上下交感，萬物資育，故是通泰之象也。「後以財成天地之道，輔相天地之宜，以左右民」者，後，君。財，裁也，剪也。道不失其宜，即是春生秋殺，各有宜也。相，助也，謂助天地所宜之物，五土所生，各以其時也。左右者，助也，謂左右群臣助君之化也。裁成天地發育所生之宜。欲明通泰之時，助天地之化，非南面之君，不可以施其化成天地之功也。</p><p>初九，拔茅茹以其匯，徵吉。茹，相牽引之貌也。夫通泰之道，天氣下降，地氣上騰，三陽皆欲上升。初為三陽之首，若行則眾類從之，猶似拔其茅根，以相連茹，以其三陽之類，陰不敢拒，所以徵進而獲吉矣。</p><p>九二，包荒，用馮河，不遐遺。「朋亡，得尚於中行」者，包，含也。荒，穢也。馮河，是無舟渡水，馮陵於河，此頑愚之人也。言九二以剛取中，心又通泰，即物無不納，雖復荒穢之物，頑愚之人，悉皆包含，不計遐遠，無所棄遺，故曰「包荒，用馮河，不遐遺也」。心既弘大，無偏無黨，即不私於朋友，天下皆悉納之，故曰「朋亡」也。亡，無也，謂無私於朋友。「得尚乎中行」者，尚，配也；中行，君也。此九二既備眾德，無物不納，即可以配於君位，下治天下也。</p><p>「九三，無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福」者，陂，險陷也；復，反也；九三處天地之際，當通泰之時，天氣降下，地氣騰上，今泰道將極，否道卻至，即天氣上升，地氣下復，猶似平路，必致崩陷，如暫往必有反覆，故曰「無平不陂，無往不復」也。時既變革，必致危殆，當須艱固其志，守正不回，乃得無咎，故曰「艱貞無咎」。眾皆同志，已去即從，故不須憂恤，而同其信，故曰「勿恤其孚」。誠信既施，德澤歸矣，自獲福慶，故曰「於食有福」。</p><p>「六四，翩翩，不富以其鄰，不戒以孚」者，翩翩者，飛動之貌也；六四處坤之首，眾陰皆隨之，故六四翩翩飛動歸於下，故曰「翩翩」。泰道既極，坤復其體，眾皆志願同歸於下，六四若行，五之與上皆相隨從，故六五、上六不待六四與之財相誘，故曰「不富以其鄰」也。鄰皆願下而不待賙贍，眾願同行，故不假戒告而自孚信，故曰「不戒以孚」也。</p><p>六五：帝乙歸妹，以祉元吉，「歸妹」猶言嫁妹也。以五貴位，降德就二，猶似帝王嫁妹於二，故曰「帝乙歸妹」也。處通泰之時，天地交好，以帝王之妹降於庶人，得配匹之宜，盡通泰之道，故獲祉福而得大吉也，故曰「以祉元吉」。祉，福也。</p><p>上六：城復於隍，勿用師，自邑告命，貞吝者，隍，城塹也。處通泰之時，上下相扶，君臣和順，猶似當初以土相培而就其城。今泰道已極，否道至，即是城之崩倒，卻至於塹，故曰「城復於隍」也。否道既至，教令不行，故不煩用師。假使歸其己邑，告戒令命，亦皆不從，是正之賤矣，故曰「勿用師，自邑告命，貞吝」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
